begin;
set local search_path=public,extensions;
select plan(21);
update auth.users set email_confirmed_at=now() where id in ('00000000-0000-4000-8000-000000000101','00000000-0000-4000-8000-000000000102','00000000-0000-4000-8000-000000000201');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000101","role":"authenticated"}',true);
create temp table owner_interval as select public.create_weekly_availability('13000000-0000-4000-8000-000000000102',2,'09:00','12:00') id;
grant select on owner_interval to authenticated,service_role;
select ok((select id is not null from owner_interval),'owner creates staff availability');
select is((select weekday from weekly_availability where id=(select id from owner_interval)),2::smallint,'interval is stored on requested weekday');
select throws_ok($$select public.create_weekly_availability('13000000-0000-4000-8000-000000000102',2,'10:00','13:00')$$,'23P01',null,'weekly overlaps are rejected');
select ok(public.create_weekly_availability('13000000-0000-4000-8000-000000000102',2,'12:00','13:00') is not null,'adjacent intervals are allowed');
select throws_ok($$select public.create_weekly_availability('13000000-0000-4000-8000-000000000102',2,'09:03','10:00')$$,'22023','invalid interval','malformed increments fail');
create temp table owner_block as select public.create_blocked_time('13000000-0000-4000-8000-000000000102','2026-09-08 09:00+00','2026-09-08 11:00+00','Internal fictional reason') id;
grant select on owner_block to authenticated,service_role;
select ok((select id is not null from owner_block),'owner creates a block');
select ok(public.create_blocked_time('13000000-0000-4000-8000-000000000102','2026-09-08 10:00+00','2026-09-08 12:00+00',null) is not null,'overlapping blocks are intentionally allowed');
select throws_ok($$insert into weekly_availability(organization_id,staff_profile_id,weekday,start_local,end_local) values('10000000-0000-4000-8000-000000000001','13000000-0000-4000-8000-000000000102',4,'09:00','10:00')$$,'42501','schedule changes require a managed operation','direct weekly writes are blocked');
select throws_ok($$delete from blocked_times where id='15000000-0000-4000-8000-000000000101'$$,'42501','schedule changes require a managed operation','direct block writes are blocked');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000102","role":"authenticated"}',true);
select ok(public.create_weekly_availability('13000000-0000-4000-8000-000000000102',3,'09:00','10:00') is not null,'staff manages own weekly availability');
select ok(public.create_blocked_time('13000000-0000-4000-8000-000000000102','2026-09-09 09:00+00','2026-09-09 10:00+00',null) is not null,'staff manages own blocks');
select throws_ok($$select public.create_weekly_availability('13000000-0000-4000-8000-000000000101',3,'09:00','10:00')$$,'42501','schedule unavailable','staff cannot manage another member');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000201","role":"authenticated"}',true);
select throws_ok($$select public.create_weekly_availability('13000000-0000-4000-8000-000000000102',4,'09:00','10:00')$$,'42501','schedule unavailable','cross-tenant owner fails closed');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000000101","role":"authenticated"}',true);
reset role;set local role service_role;update organization_memberships set status='inactive' where id='11000000-0000-4000-8000-000000000102';set local role authenticated;
select throws_ok($$select public.create_blocked_time('13000000-0000-4000-8000-000000000102','2026-09-10 09:00+00','2026-09-10 10:00+00',null)$$,'42501','schedule unavailable','inactive target membership fails closed');
reset role;set local role service_role;update organization_memberships set status='active' where id='11000000-0000-4000-8000-000000000102';select set_config('serviceflow.lifecycle_write','on',true);update organizations set status='suspended',suspended_at=now() where id='10000000-0000-4000-8000-000000000001';set local role authenticated;
select throws_ok($$select public.create_blocked_time('13000000-0000-4000-8000-000000000102','2026-09-10 09:00+00','2026-09-10 10:00+00',null)$$,'42501','schedule unavailable','suspended organization fails closed');
reset role;set local role service_role;select set_config('serviceflow.lifecycle_write','on',true);update organizations set status='published',suspended_at=null where id='10000000-0000-4000-8000-000000000001';set local role authenticated;
select ok((select relrowsecurity from pg_class where oid='public.weekly_availability'::regclass),'weekly RLS remains enabled');
select ok((select relrowsecurity from pg_class where oid='public.blocked_times'::regclass),'blocked-time RLS remains enabled');
select is((select count(*) from audit_logs where action like 'availability.%')>=2,true,'availability changes are audited');
select is((select count(*) from audit_logs where action like 'blocked_time.%')>=2,true,'blocked-time changes are audited');
select is((select count(*) from audit_logs where changes::text ilike '%Internal fictional reason%'),0::bigint,'free-form block labels are redacted from audit metadata');
reset role;set local role anon;
select throws_ok($$select public.create_weekly_availability('13000000-0000-4000-8000-000000000102',5,'09:00','10:00')$$,'42501',null,'anonymous cannot execute managed schedule RPC');
select * from finish();rollback;
